/*
 * The M0 event vocabulary the lab's fixtures were recorded in: the type section of
 * apps/desktop/src/bindings.ts at commit 5562416, generated by tauri-specta from aura-protocol.
 *
 * The lab is pinned to it on purpose. Its job, choosing the visual direction, is done (Orbit), and
 * M2a ports Orbit into the app against the live protocol, so the prototype does not chase every
 * protocol change. Regenerate nothing here: this file is a snapshot.
 */

/**  A command failure, serialized as `{ code, message }`. */
export type AppError = {
  code: AppErrorCode;
  message: string;
};

/**  What went wrong, as a stable code the UI can switch on. */
export type AppErrorCode =
  /**  An argument was outside what the command accepts. */
  | "invalid_argument"
  /**  Too many demo streams are already running. */
  | "too_many_streams"
  /**  The main window does not exist (it was closed, or creating it failed). */
  | "window_unavailable"
  /**  A command that only works in smoke mode (`AURACODE_SMOKE=1`) was called outside it. */
  | "not_in_smoke_mode"
  /**  Startup could not determine a data folder at all, so there is nothing to show. */
  | "data_dir_unknown"
  /**  The system file manager could not show the data folder. */
  | "reveal_failed"
  /**
   *  The database repair notice could not be dismissed: the database is closed, or the record of
   *  the repair could not be removed. The notice stays, and shows again on the next launch.
   */
  | "acknowledge_failed";

/**  Everything the UI needs to know about this launch, from `app_info`. */
export type AppInfo = {
  /**  auracode's version (the Cargo workspace version). */
  app_version: string;
  tauri_version: string;
  /**  `"macos"`, `"windows"`, `"linux"`, or Rust's name for another OS. */
  os: string;
  /**  The release as the OS reports it (`"26.6.2"`, `"10.0.22631"`, a Linux distribution name). */
  os_version: string;
  /**  `"aarch64"`, `"x86_64"`, ... */
  arch: string;
  /**  The data root. `null` only when no data folder could be determined at all. */
  data_dir: string | null;
  /**  `null` when startup failed before the identity was loaded (see `fatal`). */
  device: DeviceIdentity | null;
  /**  The active profile; `null` when startup failed before opening it. */
  profile: ProfileMeta | null;
  /**  The profile database; `null` when startup failed before opening it. */
  db: DbInfo | null;
  /**  The native material behind the window. `none` means the UI must paint an opaque background. */
  glass: GlassEffect;
  /**  What to open into: the normal screen, the smoke run, or the stress view. */
  launch: LaunchMode;
  /**
   *  Sentences to show: repairs startup made, launch settings that were ignored. None of them
   *  can be dismissed.
   */
  notices: string[];
  /**
   *  The notice that the database was damaged and repaired, shown on every launch until the user
   *  dismisses it (`acknowledge_recovery`): whatever the repair could not save is only in the
   *  damaged copy it names. `null` when there is none, and once it has been dismissed.
   */
  recovery_notice: string | null;
  /**  Why startup could not complete, as a sentence to show on the error screen. */
  fatal: string | null;
};

/**  One normalized event in a chat turn. */
export type AuraEvent =
  | ({ type: "turn_started"; turn_id: string } & {
      decision?: never;
      duration_ms?: never;
      entries?: never;
      level?: never;
      message?: never;
      message_id?: never;
      recoverable?: never;
      request_id?: never;
      stop_reason?: never;
      text?: never;
      thought_id?: never;
      usage?: never;
      windows?: never;
    })
  | ({ type: "turn_ended"; turn_id: string; stop_reason: StopReason; usage: TokenUsage | null } & {
      decision?: never;
      duration_ms?: never;
      entries?: never;
      level?: never;
      message?: never;
      message_id?: never;
      recoverable?: never;
      request_id?: never;
      text?: never;
      thought_id?: never;
      windows?: never;
    })
  | ({ type: "message_delta"; message_id: string; text: string } & {
      decision?: never;
      duration_ms?: never;
      entries?: never;
      level?: never;
      message?: never;
      recoverable?: never;
      request_id?: never;
      stop_reason?: never;
      thought_id?: never;
      turn_id?: never;
      usage?: never;
      windows?: never;
    })
  | ({ type: "message_completed"; message_id: string } & {
      decision?: never;
      duration_ms?: never;
      entries?: never;
      level?: never;
      message?: never;
      recoverable?: never;
      request_id?: never;
      stop_reason?: never;
      text?: never;
      thought_id?: never;
      turn_id?: never;
      usage?: never;
      windows?: never;
    })
  | ({ type: "thought_delta"; thought_id: string; text: string } & {
      decision?: never;
      duration_ms?: never;
      entries?: never;
      level?: never;
      message?: never;
      message_id?: never;
      recoverable?: never;
      request_id?: never;
      stop_reason?: never;
      turn_id?: never;
      usage?: never;
      windows?: never;
    })
  | ({ type: "thought_completed"; thought_id: string; duration_ms: number | null } & {
      decision?: never;
      entries?: never;
      level?: never;
      message?: never;
      message_id?: never;
      recoverable?: never;
      request_id?: never;
      stop_reason?: never;
      text?: never;
      turn_id?: never;
      usage?: never;
      windows?: never;
    })
  | ({
      type: "tool_call";
    } & ToolCall)
  | ({
      type: "tool_update";
    } & ToolUpdate)
  | ({
      type: "permission_requested";
    } & PermissionRequest)
  | ({ type: "permission_resolved"; request_id: string; decision: PermissionDecision } & {
      duration_ms?: never;
      entries?: never;
      level?: never;
      message?: never;
      message_id?: never;
      recoverable?: never;
      stop_reason?: never;
      text?: never;
      thought_id?: never;
      turn_id?: never;
      usage?: never;
      windows?: never;
    })
  | ({
      type: "ui_request";
    } & UiRequest)
  | ({ type: "plan_updated"; entries: PlanEntry[] } & {
      decision?: never;
      duration_ms?: never;
      level?: never;
      message?: never;
      message_id?: never;
      recoverable?: never;
      request_id?: never;
      stop_reason?: never;
      text?: never;
      thought_id?: never;
      turn_id?: never;
      usage?: never;
      windows?: never;
    })
  | ({
      type: "usage_updated";
    } & UsageInfo)
  | ({ type: "limits_updated"; windows: LimitWindow[] } & {
      decision?: never;
      duration_ms?: never;
      entries?: never;
      level?: never;
      message?: never;
      message_id?: never;
      recoverable?: never;
      request_id?: never;
      stop_reason?: never;
      text?: never;
      thought_id?: never;
      turn_id?: never;
      usage?: never;
    })
  | ({
      type: "session_updated";
    } & SessionInfo)
  | ({ type: "notice"; level: NoticeLevel; message: string } & {
      decision?: never;
      duration_ms?: never;
      entries?: never;
      message_id?: never;
      recoverable?: never;
      request_id?: never;
      stop_reason?: never;
      text?: never;
      thought_id?: never;
      turn_id?: never;
      usage?: never;
      windows?: never;
    })
  | ({ type: "error"; message: string; recoverable: boolean } & {
      decision?: never;
      duration_ms?: never;
      entries?: never;
      level?: never;
      message_id?: never;
      request_id?: never;
      stop_reason?: never;
      text?: never;
      thought_id?: never;
      turn_id?: never;
      usage?: never;
      windows?: never;
    });

export type Cost = {
  amount: number | null;
  currency: string;
};

/**  The profile database as the info card shows it. */
export type DbInfo = {
  path: string;
  schema_version: number;
  /**  What opening the database had to do (create, migrate, recover). */
  outcome: OpenOutcome;
};

/**  Which scripted turn to play. */
export type DemoKind =
  /**  A realistic turn: a thought, a file read, an edit, a plan, a markdown answer, usage. */
  | { type: "demo" }
  /**  A long, fast markdown answer of exactly `total_tokens` tokens, for the stress view. */
  | { type: "stress"; total_tokens: number };

/**  Who this machine is, as stored in `device.json`. */
export type DeviceIdentity = {
  /**  Lowercase hyphenated UUIDv7, generated once per machine. */
  device_id: string;
  name: string;
  /**  `"macos"`, `"windows"`, `"linux"`, or Rust's `std::env::consts::OS` elsewhere. */
  platform: string;
  /**
   *  Unix ms. Exported to TypeScript as `number` (specta refuses `i64` by default); exact until
   *  2^53 ms, hundreds of millennia away.
   */
  created_at: number;
};

/**
 *  A frame of events for one session, sent from the core to the UI over a Tauri channel.
 *
 *  `seq_start` is the session-wide sequence number of the first event, so the UI can detect gaps and
 *  drop duplicates after a reconnect.
 */
export type EventBatch = {
  session_id: string;
  seq_start: number;
  events: AuraEvent[];
};

/**
 *  The material the window got, reported to the UI in `app_info`. `none` tells the UI to paint
 *  its own opaque background.
 */
export type GlassEffect = "liquid_glass" | "vibrancy" | "mica" | "none";

/**
 *  What the UI should open into. Smoke mode wins over the stress view, since it is the one that
 *  exits by itself and a CI job is waiting on it.
 */
export type LaunchMode =
  | { type: "normal" }
  | { type: "smoke" }
  | { type: "stress"; config: StressConfig };

/**  One account rate-limit window (Claude's five-hour/weekly windows, Codex's primary/secondary). */
export type LimitWindow = {
  label: string;
  used_percent: number | null;
  resets_at: number | null;
};

export type NoticeLevel = "info" | "warning";

/**  What [`Store::open`] had to do. Paths are strings so the UI can show them as they are. */
export type OpenOutcome =
  /**  No database existed; a new one was created at the current schema. */
  | { type: "created" }
  /**  The database was already at the current schema. */
  | { type: "opened" }
  /**  The database was upgraded. `backup` is the copy taken first. */
  | { type: "migrated"; from: number; to: number; backup: string | null }
  /**
   *  The database was damaged. It was moved to `quarantined`, where it is kept, and everything
   *  that could still be read from it was copied into the database that replaced it; `salvage`
   *  says how much that was. Reported on every open until [`Store::acknowledge_recovery`], so the
   *  UI can't miss it: whatever the copy lacks is only in the quarantined file.
   */
  | { type: "recovered_from_corruption"; quarantined: string; salvage: Salvage };

export type PermissionDecision = { type: "selected"; option_id: string } | { type: "cancelled" };

export type PermissionOption = {
  option_id: string;
  kind: PermissionOptionKind;
  label: string;
};

export type PermissionOptionKind = "allow_once" | "allow_always" | "reject_once" | "reject_always";

/**  The agent asks the user before running a tool (only outside Full auto). */
export type PermissionRequest = {
  request_id: string;
  tool_call_id: string | null;
  title: string;
  options: PermissionOption[];
};

export type PlanEntry = {
  content: string;
  status: PlanStatus;
  priority: PlanPriority | null;
};

export type PlanPriority = "high" | "medium" | "low";

export type PlanStatus = "pending" | "in_progress" | "completed";

export type ProfileKind =
  /**  Data that lives only on this machine. */
  | "local"
  /**  Data that belongs to a signed-in account (M6/M7). */
  | "account";

/**  The contents of `profile.json`. */
export type ProfileMeta = {
  id: string;
  kind: ProfileKind;
  display_name: string;
  /**  Unix ms, exported to TypeScript as `number` (see `DeviceIdentity::created_at`). */
  created_at: number;
};

/**  How much of a damaged database made it into the database that replaced it. */
export type Salvage =
  /**
   *  Every table read back without an error, so nothing is missing: the damage was in pages no
   *  row lives in (unused pages, a broken index), which the copy rebuilt.
   */
  | { type: "complete" }
  /**
   *  Some rows could not be read, or were dropped because the row they belong to was lost (a
   *  chat's events, when the chat's page was unreadable), or lost a reference to such a row (a
   *  chat whose folder was lost stays in its project, outside any folder). `tables` names those
   *  tables, in schema order. It is empty when which ones isn't known: part of the schema itself
   *  was unreadable (and may have listed tables auracode doesn't know of), or the record of the
   *  repair could not be read.
   */
  | { type: "partial"; tables: string[] }
  /**  Nothing could be read, so the new database started out empty. */
  | { type: "nothing" };

/**  What the agent currently reports about the session. */
export type SessionInfo = {
  native_session_id: string | null;
  title: string | null;
  model: string | null;
  effort: string | null;
  mode: string | null;
  commands: SlashCommand[];
};

export type SlashCommand = {
  name: string;
  description: string;
  input_hint: string | null;
};

/**  What the UI's smoke run measured. */
export type SmokeReport = {
  ok: boolean;
  /**  Events applied across every stream of the run. */
  events_received: number;
  /**  Frames (`EventBatch`es) received across every stream of the run. */
  frames_received: number;
  /**  Sequence gaps the stream reducer detected. Any gap fails the run. */
  seq_gaps: number;
  /**  Characters of streamed answer text present in the rendered DOM. */
  rendered_chars: number;
  /**  Lowest frame rate over half-second windows of the stress burst. */
  fps_min: number | null;
  /**  Average frame rate over the stress burst. */
  fps_avg: number | null;
  errors: string[];
};

/**  Why a turn ended. */
export type StopReason =
  | "end_turn"
  | "max_tokens"
  | "max_turn_requests"
  | "refusal"
  | "cancelled"
  | "error";

/**
 *  Settings for the stress view: `orbs` live orbs, a stream at `rate` tokens per second, the aura
 *  field on or off, for `seconds` seconds (0 keeps streaming until the window closes).
 */
export type StressConfig = {
  orbs: number;
  rate: number;
  aura: boolean;
  seconds: number;
};

/**  Token accounting for a turn, when the agent reports it. */
export type TokenUsage = {
  input_tokens: number;
  output_tokens: number;
  cached_input_tokens: number | null;
  reasoning_tokens: number | null;
};

/**  A tool invocation started by the agent. */
export type ToolCall = {
  tool_call_id: string;
  kind: ToolKind;
  title: string;
  status: ToolStatus;
  locations: ToolLocation[];
  /**  The tool's raw input as the agent sent it, for the expanded view. */
  raw_input: Value | null;
};

/**  Rich content attached to a tool update. */
export type ToolContent =
  | { type: "text"; text: string }
  | {
      type: "diff";
      path: string;
      /**  `None` when the file is new. */
      old_text: string | null;
      new_text: string;
    }
  | {
      type: "terminal";
      output: string;
      exit_code: number | null;
      /**  Set when `output` was cut for the UI; the full output lives on disk. */
      truncated: boolean;
    };

export type ToolKind =
  | "read"
  | "edit"
  | "delete"
  | "move"
  | "search"
  | "execute"
  | "think"
  | "fetch"
  | "switch_mode"
  | "other";

export type ToolLocation = {
  path: string;
  line: number | null;
};

export type ToolStatus = "pending" | "in_progress" | "completed" | "failed";

/**  Progress or result for a previously announced [`ToolCall`]. */
export type ToolUpdate = {
  tool_call_id: string;
  status: ToolStatus | null;
  title: string | null;
  content: ToolContent[];
};

export type UiPrompt =
  | { type: "confirm"; message: string }
  | { type: "select"; message: string; options: string[] }
  | { type: "input"; message: string; placeholder: string | null }
  | { type: "notify"; message: string };

/**
 *  An agent asks the UI for input that isn't a tool permission (Pi extension UI, Cursor questions,
 *  ACP elicitation).
 */
export type UiRequest = {
  request_id: string;
  prompt: UiPrompt;
};

/**  Context-window and spend information for the session. */
export type UsageInfo = {
  context_used: number | null;
  context_size: number | null;
  cost: Cost | null;
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };
